def celsius_to_fahrenheit(c):
    return c * 9 / 5 + 32


def fahrenheit_to_celsius(f):
    return (f - 32) * 5 / 9


def celsius_to_kelvin(c):
    return c + 273.15


CONVERTERS = {
    "c2f": celsius_to_fahrenheit,
    "f2c": fahrenheit_to_celsius,
    "c2k": celsius_to_kelvin,
}

if __name__ == "__main__":
    command = input().strip()
    value = float(input())
    print(f"{CONVERTERS[command](value):.2f}")

import random

seed, k = map(int, input().split())
random.seed(seed)

rolls = []
for _ in range(k):
    rolls.append(random.randint(1, 6))

counts = [0] * 7
for face in rolls:
    counts[face] += 1

streak = 1
best_streak = 1
for i in range(1, k):
    if rolls[i] == rolls[i - 1]:
        streak += 1
        if streak > best_streak:
            best_streak = streak
    else:
        streak = 1

pairs = 0
for i in range(1, k):
    if rolls[i] == rolls[i - 1]:
        pairs += 1

best_face, best_count = 0, -1
for face in range(1, 7):
    if counts[face] > best_count:
        best_face, best_count = face, counts[face]

print(" ".join(str(c) for c in counts[1:]))
print(best_streak)
print(best_face)
print(pairs)

import math


def circle_area(r):
    return math.pi * r * r


def triangle_area(a, b, c):
    if a <= 0 or b <= 0 or c <= 0:
        return None
    if a + b <= c or a + c <= b or b + c <= a:
        return None
    s = (a + b + c) / 2
    return math.sqrt(s * (s - a) * (s - b) * (s - c))


def distance(x1, y1, x2, y2):
    return math.hypot(x2 - x1, y2 - y1)


if __name__ == "__main__":
    n = int(input())
    for _ in range(n):
        parts = input().split()
        cmd = parts[0]
        args = [float(x) for x in parts[1:]]
        if cmd == "circle":
            print(f"{circle_area(args[0]):.2f}")
        elif cmd == "tri":
            area = triangle_area(args[0], args[1], args[2])
            if area is None:
                print("Invalid triangle")
            else:
                print(f"{area:.2f}")
        elif cmd == "dist":
            print(f"{distance(*args):.2f}")

def shout(text):
    return text.upper()


def whisper(text):
    return text.lower()


def mirror(text):
    return text[::-1]


def repeat(text, times):
    return text * times


COMMANDS = {"shout": shout, "whisper": whisper, "mirror": mirror, "repeat": repeat}

if __name__ == "__main__":
    n = int(input())
    good = 0
    bad = 0
    for _ in range(n):
        line = input()
        name, _, rest = line.partition(" ")
        if name in COMMANDS:
            good += 1
            if name == "repeat":
                word, times = rest.rsplit(" ", 1)
                print(COMMANDS[name](word, int(times)))
            else:
                print(COMMANDS[name](rest))
        else:
            bad += 1
            print("Unknown command")
    print(f"ok {good} bad {bad}")

import os

CODE_EXT = {"py", "js", "ts"}
DATA_EXT = {"json", "csv", "yaml", "xml"}
DOC_EXT = {"md", "txt"}

base = input()
n = int(input())
counts = {"code": 0, "data": 0, "doc": 0, "other": 0}
for _ in range(n):
    name = input()
    full = os.path.join(base, name)
    ext = os.path.splitext(full)[1]
    leaf = os.path.basename(full)
    if ext == "":
        kind = "other"
        shown = "none"
    else:
        shown = ext[1:]
        if shown in CODE_EXT:
            kind = "code"
        elif shown in DATA_EXT:
            kind = "data"
        elif shown in DOC_EXT:
            kind = "doc"
        else:
            kind = "other"
    counts[kind] += 1
    print(f"{leaf} {shown} {kind}")
print(f"code {counts['code']} data {counts['data']} doc {counts['doc']} other {counts['other']}")
